"""One-time, hash-checked integration of the reviewed 1.4 renderer.
The release workflow commits the expanded readable files and removes this helper.
Combat and persistence modules are not edited.
"""
import base64, hashlib, json, zlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PAYLOAD=''''''
raw=zlib.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(raw).hexdigest()=='b137fc02741a2712df9a3b41baabc7a08f3edb9c93bbb9ea33937048c3365dc0','Transfer checksum mismatch'
files=json.loads(raw)
for relative,item in files.items():
 path=(ROOT/relative).resolve();assert path.is_relative_to(ROOT)
 old=path.read_text();digest=hashlib.sha256(old.encode()).hexdigest()
 if digest==item['after']:continue
 assert digest==item['before'],'Source changed since review: '+relative
 for start,end,new in reversed(item['ops']):old=old[:start]+new+old[end:]
 assert hashlib.sha256(old.encode()).hexdigest()==item['after'],relative
 path.write_text(old);print('Integrated',relative)
p=ROOT/'src/renderer3d.js'
s=p.read_text().replace('time*1.6+(state.id||0)','time*1.6+(Number.isFinite(state.id)?state.id:0)')
p.write_text(s)
